        s.scene = intOr(o, "scene", -1);
        if (s.scene < 0 || s.scene > 1000) {
            errs.add(w + ": scene must be an integer 0..1000");
        }
        s.name = str(o, "name");
        if (s.name == null || !s.name.matches("[A-Za-z0-9_.@-]{1,120}")) {
            errs.add(w + ": name must match [A-Za-z0-9_.@-]{1,120}");
        }
        s.start = intOr(o, "start", -1);
        s.end = intOr(o, "end", -1);
        if (o.has("start") && !o.get("start").isJsonNull() && !isInt(o.get("start"))) {
            errs.add(w + ": start must be an integer or null");
        }
        if (o.has("end") && !o.get("end").isJsonNull() && !isInt(o.get("end"))) {
            errs.add(w + ": end must be an integer or null");
        }
        if (s.start >= 0 && s.end >= 0 && s.end <= s.start) {
            errs.add(w + ": end must be greater than start");
        }
        if ((s.start >= 0) != (s.end >= 0)) {
            errs.add(w + ": give both start and end, or neither");
        }
        String out = str(o, "output");
        if (out == null || out.isBlank()) {
            errs.add(w + ": output missing");
        } else {
