/** Tiny logging seam so the pure classes can be tested without Minecraft or log4j. */
public interface Log {
    void info(String msg);

    void warn(String msg);

    void error(String msg, Throwable t);

    /** Prints to stdout (used by the self test). */
    Log STDOUT = new Log() {
        @Override
        public void info(String msg) {
            System.out.println("[flashback_auto] " + msg);
        }

        @Override
        public void warn(String msg) {
            System.out.println("[flashback_auto] WARN " + msg);
        }

        @Override
        public void error(String msg, Throwable t) {
            System.out.println("[flashback_auto] ERROR " + msg + (t == null ? "" : " " + t));
        }
    };
}

