package dev.crodie.flashbackauto;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Parsed and validated job file (the JSON written by studio/mcstudio/flashback_keyframes.py::jobs_json).
 * No Minecraft dependency: enum names are validated against fixed lists here and mapped to Flashback enums by the runner.
 */
public final class JobSpec {
    public static final Set<String> CONTAINERS = new HashSet<>(Arrays.asList(
            "MP4", "MKV", "AVI", "MOV", "PNG_SEQUENCE", "WEBP", "WEBM", "GIF"));
    public static final Set<String> CODECS = new HashSet<>(Arrays.asList(
            "H264", "H265", "AV1", "VP9", "PRO_RES", "QUICK_TIME", "WEBP", "GIF"));

    public static final class Shot {
        public int scene;
        public String name;
        /** Replay ticks; -1 = take from the scene (export range, else first/last keyframe, else whole replay). */
        public int start = -1;
        public int end = -1;
        public Path output;
        public int width;
        public int height;
        public double fps;
        public String container;
        public String codec;
        /** null = Flashback's first valid encoder for the codec. */
        public String encoder;
        /** bits per second; 0 = maximum. */
        public int bitrate;
        public boolean ssaa;
        public boolean noGui;
        public boolean resetRng;
        public boolean recordAudio;
        public boolean transparent;
        public String kind = "";

        public boolean isPngSequence() {
            return "PNG_SEQUENCE".equals(container);
        }
    }

    public Path file;
    public Path replay;
    public final List<Shot> shots = new ArrayList<>();
    /** Overall watchdog in seconds (job file key "watchdog_s", default 2700 = 45 min). */
    public int watchdogSeconds = 2700;

    public static final class JobException extends Exception {
        private static final long serialVersionUID = 1L;
        public final transient List<String> problems;

        public JobException(List<String> problems) {
            super(String.join("; ", problems));
            this.problems = problems;
        }
    }

    private JobSpec() {
    }

    public static JobSpec parse(Path jobFile) throws JobException {
        List<String> errs = new ArrayList<>();
        JsonObject root;
        try (Reader r = Files.newBufferedReader(jobFile, StandardCharsets.UTF_8)) {
            JsonElement el = JsonParser.parseReader(r);
            if (!el.isJsonObject()) {
                throw new JobException(List.of("job file is not a JSON object"));
            }
            root = el.getAsJsonObject();
        } catch (IOException | RuntimeException e) {
            throw new JobException(List.of("cannot read job file " + jobFile + ": " + e));
        }
        JobSpec spec = new JobSpec();
        spec.file = jobFile.toAbsolutePath().normalize();

        if (!root.has("version") || !isInt(root.get("version")) || root.get("version").getAsInt() != 1) {
            errs.add("version must be 1");
        }
        String replay = str(root, "replay");
        if (replay == null || replay.isBlank()) {
            errs.add("replay path missing");
        } else {
            Path rp = Path.of(replay);
            if (!rp.isAbsolute()) {
                errs.add("replay path must be absolute: " + replay);
            } else if (!replay.toLowerCase(Locale.ROOT).endsWith(".zip")) {
                errs.add("replay must be a Flashback .zip: " + replay);
            } else if (!Files.isRegularFile(rp)) {
                errs.add("replay file not found: " + replay);
            } else {
                spec.replay = rp.normalize();
            }
        }
        if (root.has("watchdog_s")) {
            if (isInt(root.get("watchdog_s")) && root.get("watchdog_s").getAsInt() >= 60
                    && root.get("watchdog_s").getAsInt() <= 6 * 3600) {
                spec.watchdogSeconds = root.get("watchdog_s").getAsInt();
            } else {
                errs.add("watchdog_s must be an integer between 60 and 21600");
            }
        }
        JsonArray jobs = root.has("jobs") && root.get("jobs").isJsonArray() ? root.getAsJsonArray("jobs") : null;
        if (jobs == null || jobs.size() == 0) {
            errs.add("jobs must be a non-empty array");
        } else if (jobs.size() > 200) {
            errs.add("too many jobs (" + jobs.size() + " > 200)");
        } else {
            Set<String> outputs = new HashSet<>();
            for (int i = 0; i < jobs.size(); i++) {
                String w = "jobs[" + i + "]";
                if (!jobs.get(i).isJsonObject()) {
                    errs.add(w + " is not an object");
                    continue;
                }
                Shot s = parseShot(jobs.get(i).getAsJsonObject(), w, errs);
                if (s != null) {
                    if (s.output != null && !outputs.add(s.output.toString().toLowerCase(Locale.ROOT))) {
                        errs.add(w + ": duplicate output " + s.output);
                    }
                    spec.shots.add(s);
                }
            }
        }
        if (!errs.isEmpty()) {
            throw new JobException(errs);
        }
        return spec;
    }

    private static Shot parseShot(JsonObject o, String w, List<String> errs) {
        int before = errs.size();
        Shot s = new Shot();
        s.scene = intOr(o, "scene", -1);
        if (s.scene < 0 || s.scene > 1000) {
            errs.add(w + ": scene must be an integer 0..1000");
        }
        s.name = str(o, "name");
        if (s.name == null || !s.name.matches("[A-Za-z0-9_.@-]{1,120}")) {
            errs.add(w + ": name must match [A-Za-z0-9_.@-]{1,120}");
        }
        s.start = intOr(o, "start", -1);
        s.end = intOr(o, "end", -1);
        if (o.has("start") && !o.get("start").isJsonNull() && !isInt(o.get("start"))) {
            errs.add(w + ": start must be an integer or null");
        }
        if (o.has("end") && !o.get("end").isJsonNull() && !isInt(o.get("end"))) {
            errs.add(w + ": end must be an integer or null");
        }
        if (s.start >= 0 && s.end >= 0 && s.end <= s.start) {
            errs.add(w + ": end must be greater than start");
        }
        if ((s.start >= 0) != (s.end >= 0)) {
            errs.add(w + ": give both start and end, or neither");
        }
        String out = str(o, "output");
        if (out == null || out.isBlank()) {
            errs.add(w + ": output missing");
        } else {
            Path p = Path.of(out);
            if (!p.isAbsolute()) {
                errs.add(w + ": output must be absolute: " + out);
            } else {
                s.output = p.normalize();
            }
        }
        s.width = intOr(o, "width", 1920);
        s.height = intOr(o, "height", 1080);
        if (s.width < 64 || s.width > 7680 || s.height < 64 || s.height > 4320 || s.width % 2 != 0 || s.height % 2 != 0) {
            errs.add(w + ": width/height must be even, 64..7680 x 64..4320");
        }
        s.fps = o.has("fps") && o.get("fps").isJsonPrimitive() && o.get("fps").getAsJsonPrimitive().isNumber()
                ? o.get("fps").getAsDouble() : 60.0;
        if (!(s.fps >= 1.0 && s.fps <= 240.0)) {
            errs.add(w + ": fps must be 1..240");
        }
        s.container = upper(str(o, "container"), "MP4");
        if (!CONTAINERS.contains(s.container)) {
            errs.add(w + ": unknown container " + s.container);
        }
        s.codec = upper(str(o, "codec"), "H264");
        if (!CODECS.contains(s.codec)) {
            errs.add(w + ": unknown codec " + s.codec);
        }
        s.encoder = str(o, "encoder");
        if (s.encoder != null) {
            if (s.encoder.isBlank()) {
                s.encoder = null;
            } else if (!s.encoder.matches("[A-Za-z0-9_]{1,40}")) {
                errs.add(w + ": invalid encoder name " + s.encoder);
            }
        }
        s.bitrate = intOr(o, "bitrate", 20_000_000);
        if (s.bitrate < 0 || s.bitrate > 2_000_000_000) {
            errs.add(w + ": bitrate must be 0..2000000000 (0 = maximum)");
        }
        s.ssaa = bool(o, "ssaa", false);
        s.noGui = bool(o, "noGui", true);
        s.resetRng = bool(o, "resetRng", false);
        s.recordAudio = bool(o, "recordAudio", false);
        s.transparent = bool(o, "transparent", false);
        String kind = str(o, "kind");
        s.kind = kind == null ? "" : kind;
        if (s.output != null && CONTAINERS.contains(s.container) && !s.isPngSequence()) {
            String ext = "." + s.container.toLowerCase(Locale.ROOT);
            if (!s.output.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(ext)) {
                errs.add(w + ": output should end with " + ext);
            }
        }
        return errs.size() == before ? s : null;
    }

    private static boolean isInt(JsonElement e) {
        if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber()) {
            return false;
        }
        double d = e.getAsDouble();
        return d == Math.rint(d) && Math.abs(d) < 2e9;
    }

    private static int intOr(JsonObject o, String k, int dflt) {
        JsonElement e = o.get(k);
        if (e == null || e.isJsonNull() || !isInt(e)) {
            return dflt;
        }
        return e.getAsInt();
    }

    private static boolean bool(JsonObject o, String k, boolean dflt) {
        JsonElement e = o.get(k);
        if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isBoolean()) {
            return dflt;
        }
        return e.getAsBoolean();
    }

    private static String str(JsonObject o, String k) {
        JsonElement e = o.get(k);
        if (e == null || e.isJsonNull() || !e.isJsonPrimitive()) {
            return null;
        }
        return e.getAsString();
    }

    private static String upper(String s, String dflt) {
        return s == null || s.isBlank() ? dflt : s.trim().toUpperCase(Locale.ROOT);
    }
}

