    public static Result check(String jobProp, String tokenProp, long nowMs) {
        if (jobProp == null || jobProp.isBlank()) {
            return new Result(false, "no -D" + PROP_JOB, null);
        }
        Path job;
        try {
            job = Path.of(jobProp).toAbsolutePath().normalize();
        } catch (RuntimeException e) {
