        }
        Path armed = job.resolveSibling(ARMED_FILE);
        if (!Files.isRegularFile(armed)) {
            return new Result(false, "no ARMED marker next to the job file", job);
        }
        JsonObject m;
        try {
            m = JsonParser.parseString(Files.readString(armed, StandardCharsets.UTF_8)).getAsJsonObject();
        } catch (Exception e) {
            return new Result(false, "ARMED marker unreadable", job);
        }
        if (!m.has("job") || !m.has("created") || !m.get("job").isJsonPrimitive() || !m.get("created").isJsonPrimitive()) {
            return new Result(false, "ARMED marker incomplete", job);
        }
        Path markerJob;
        double created;
        try {
            markerJob = Path.of(m.get("job").getAsString()).toAbsolutePath().normalize();
            created = m.get("created").getAsDouble();
        } catch (RuntimeException e) {
            return new Result(false, "ARMED marker malformed", job);
        }
        if (!sameFile(markerJob, job)) {
            return new Result(false, "ARMED marker names a different job file", job);
        }
        double age = nowMs / 1000.0 - created;
        if (age > MAX_AGE_S) {
            return new Result(false, "ARMED marker is stale (" + (long) age + " s old)", job);
        }
        if (age < -60) {
            return new Result(false, "ARMED marker is dated in the future", job);
        }
        if (m.has("token") && m.get("token").isJsonPrimitive()) {
            String want = m.get("token").getAsString();
            if (tokenProp == null || !want.equals(tokenProp)) {
                return new Result(false, "ARMED token does not match -D" + PROP_TOKEN, job);
            }
        }
        return new Result(true, "armed", job);
    }

    private static boolean sameFile(Path a, Path b) {
        return a.toString().toLowerCase(Locale.ROOT).equals(b.toString().toLowerCase(Locale.ROOT));
    }
}

