package dev.crodie.flashbackauto;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import java.io.IOException;
import java.io.PrintWriter;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

/** Writes status.json (temp file + replace) next to the job file. Thread-safe. */
public final class StatusWriter {
    public static final String STATUS_FILE = "status.json";
    public static final String STOP_FILE = "STOP";
    public static final String MOD_VERSION = "0.1.0";

    private final Path statusPath;
    private final Gson gson = new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().create();
    private final long startedMs = System.currentTimeMillis();

    public volatile String state = "starting";
    public volatile String message = "";
    public volatile int jobIndex = -1;
    public volatile int jobCount = 0;
    public volatile String jobName = null;
    public volatile int progressPct = 0;
    public volatile int frames = 0;
    public volatile int totalFrames = 0;
    private final JsonArray results = new JsonArray();
    private final JsonArray errors = new JsonArray();
    private volatile long lastWriteMs = 0;

    public StatusWriter(Path jobFile) {
        this.statusPath = jobFile.resolveSibling(STATUS_FILE);
    }

    public Path path() {
        return statusPath;
    }

    public synchronized void addResult(JsonObject r) {
        results.add(r);
    }

    public synchronized void addError(String msg, Throwable t) {
        JsonObject e = new JsonObject();
        e.addProperty("message", msg);
        if (t != null) {
            StringWriter sw = new StringWriter();
            t.printStackTrace(new PrintWriter(sw));
            e.addProperty("stack", sw.toString());
        }
        errors.add(e);
    }

    public long msSinceWrite() {
        return System.currentTimeMillis() - lastWriteMs;
    }

    public synchronized void write() {
        JsonObject o = new JsonObject();
        o.addProperty("modVersion", MOD_VERSION);
        o.addProperty("state", state);
        o.addProperty("message", message);
        o.addProperty("pid", ProcessHandle.current().pid());
        o.addProperty("startedMs", startedMs);
        o.addProperty("updatedMs", System.currentTimeMillis());
        o.addProperty("jobIndex", jobIndex);
        o.addProperty("jobCount", jobCount);
        o.addProperty("job", jobName);
        o.addProperty("progressPct", progressPct);
        o.addProperty("frames", frames);
        o.addProperty("totalFrames", totalFrames);
        o.add("results", results.deepCopy());
        o.add("errors", errors.deepCopy());
        Path tmp = statusPath.resolveSibling(STATUS_FILE + ".tmp");
        try {
            Files.writeString(tmp, gson.toJson(o), StandardCharsets.UTF_8);
            try {
                Files.move(tmp, statusPath, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            } catch (IOException atomicFailed) {
                Files.move(tmp, statusPath, StandardCopyOption.REPLACE_EXISTING);
            }
            lastWriteMs = System.currentTimeMillis();
        } catch (IOException e) {
            // Status is best effort; the driver also watches the process.
            System.err.println("[flashback_auto] cannot write status: " + e);
        }
    }
}

