package dev.crodie.flashbackauto;

import net.fabricmc.api.ClientModInitializer;

/**
 * Client entrypoint. In a normal play session this does exactly one thing: read one JVM system property and return.
 * No thread, no tick hook, no file access, no UI, no network. Only when the studio launched the game in render mode
 * (-Dflashback_auto.job=... AND a fresh matching ARMED file) is {@link AutoRunner} even loaded.
 * This class must not reference any Minecraft or Flashback type.
 */
public final class FlashbackAutoMod implements ClientModInitializer {
    @Override
    public void onInitializeClient() {
        String job = System.getProperty(ArmedCheck.PROP_JOB);
        if (job == null || job.isEmpty()) {
            return; // inert: normal play
        }
        ArmedCheck.Result r = ArmedCheck.check(job, System.getProperty(ArmedCheck.PROP_TOKEN), System.currentTimeMillis());
        if (!r.armed) {
            System.out.println("[flashback_auto] inert: " + r.reason);
            return;
        }
        AutoRunner.start(r.jobFile);
    }
}

