    private static final long GAME_WAIT_MS = 180_000;
    private static final long OPEN_TIMEOUT_MS = 120_000;
    private static final long STALL_MS = 300_000;
    private static final long START_TIMEOUT_MS = 120_000;
    private static final long STOP_GRACE_MS = 30_000;
    private static final long STATUS_EVERY_MS = 2_000;

    private final Path jobFile;
    private final Path stopFile;
    private final Path modLog;
    private final StatusWriter status;
