    private volatile long stopRequestedMs = 0;
    private volatile long phaseSinceMs = System.currentTimeMillis();
    private volatile long lastProgressChangeMs = System.currentTimeMillis();
    private volatile int lastProgressCount = -1;

    // render-thread state (only touched inside step())
    private int gameReadySteps = 0;
    private int readyStreak = 0;
    private int idx = 0;
    private boolean anyFailed = false;
    private long shotStartMs = 0;
    private ExportJob currentJob = null;
    private long lastDiagMs = 0;

    private AutoRunner(Path jobFile) {
        this.jobFile = jobFile;
        this.stopFile = jobFile.resolveSibling(StatusWriter.STOP_FILE);
