package dev.crodie.flashbackauto;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/** Pure-Java checks of the Minecraft-free classes. Run: java -cp build/classes;gson.jar dev.crodie.flashbackauto.SelfTest */
public final class SelfTest {
    private static int failures = 0;
    private static int checks = 0;

    private static void check(boolean cond, String what) {
        checks++;
        if (!cond) {
            failures++;
            System.out.println("FAIL: " + what);
        }
    }

    private static void write(Path p, String s) throws Exception {
        Files.writeString(p, s, StandardCharsets.UTF_8);
    }

    private static String marker(Path job, long createdS, String token) {
        JsonObject o = new JsonObject();
        o.addProperty("job", job.toString());
        o.addProperty("created", createdS);
        if (token != null) {
            o.addProperty("token", token);
        }
        return o.toString();
    }

    public static void main(String[] args) throws Exception {
        Path dir = Files.createTempDirectory("fa_selftest");
        Path replay = dir.resolve("replay.zip");
        Files.write(replay, new byte[]{1, 2, 3});
        Path job = dir.resolve("job.json");
        String good = "{\"version\":1,\"replay\":" + quote(replay) + ",\"jobs\":[{\"scene\":0,\"name\":\"00_orbit\",\"start\":100,\"end\":220,"
                + "\"output\":" + quote(dir.resolve("out").resolve("00_orbit.mp4")) + ",\"width\":1920,\"height\":1080,\"fps\":60.0,"
                + "\"container\":\"MP4\",\"codec\":\"H264\",\"encoder\":null,\"bitrate\":20000000,\"ssaa\":false,\"noGui\":true,"
                + "\"resetRng\":false,\"recordAudio\":false,\"transparent\":false,\"kind\":\"orbit\",\"note\":\"x\"}]}";
        write(job, good);
        long now = System.currentTimeMillis();

        // ---- ArmedCheck
        check(!ArmedCheck.check(null, null, now).armed, "no property -> inert");
        check(!ArmedCheck.check("", null, now).armed, "empty property -> inert");
        check(!ArmedCheck.check(job.toString(), null, now).armed, "no marker -> inert");
        Path armed = dir.resolve("ARMED");
        write(armed, marker(job, now / 1000, null));
        check(ArmedCheck.check(job.toString(), null, now).armed, "fresh matching marker -> armed");
        write(armed, marker(job, now / 1000 - 601, null));
        check(!ArmedCheck.check(job.toString(), null, now).armed, "stale marker -> inert");
        write(armed, marker(job, now / 1000 + 3600, null));
        check(!ArmedCheck.check(job.toString(), null, now).armed, "future marker -> inert");
        write(armed, marker(dir.resolve("other.json"), now / 1000, null));
        check(!ArmedCheck.check(job.toString(), null, now).armed, "marker for other job -> inert");
        write(armed, "not json");
        check(!ArmedCheck.check(job.toString(), null, now).armed, "garbage marker -> inert");
        write(armed, "{\"job\":\"x\"}");
        check(!ArmedCheck.check(job.toString(), null, now).armed, "incomplete marker -> inert");
        write(armed, marker(job, now / 1000, "abc"));
        check(ArmedCheck.check(job.toString(), "abc", now).armed, "token match -> armed");
        check(!ArmedCheck.check(job.toString(), "zzz", now).armed, "token mismatch -> inert");
        check(!ArmedCheck.check(job.toString(), null, now).armed, "token missing in JVM args -> inert");
        write(armed, marker(job, now / 1000 - 599, null));
        check(ArmedCheck.check(job.toString(), null, now).armed, "599 s old marker still valid");
        Files.delete(armed);

        // ---- JobSpec
        JobSpec spec = JobSpec.parse(job);
        check(spec.shots.size() == 1, "one shot parsed");
        JobSpec.Shot s = spec.shots.get(0);
        check(s.scene == 0 && s.start == 100 && s.end == 220 && s.width == 1920 && s.fps == 60.0, "shot fields");
        check("MP4".equals(s.container) && "H264".equals(s.codec) && s.encoder == null && s.noGui, "shot enums/defaults");
        check(spec.watchdogSeconds == 2700, "default watchdog 45 min");

        expectFail(dir, good.replace("\"version\":1", "\"version\":2"), "bad version");
        expectFail(dir, good.replace("\"MP4\"", "\"EXE\""), "bad container");
        expectFail(dir, good.replace("\"H264\"", "\"H999\""), "bad codec");
        expectFail(dir, good.replace("\"start\":100", "\"start\":300"), "end <= start");
        expectFail(dir, good.replace("\"width\":1920", "\"width\":1921"), "odd width");
        expectFail(dir, good.replace("60.0", "1000"), "fps too high");
        expectFail(dir, good.replace("00_orbit.mp4", "00_orbit.avi"), "wrong extension");
        expectFail(dir, good.replace("\"name\":\"00_orbit\"", "\"name\":\"../evil\""), "bad name");
        expectFail(dir, good.replaceFirst("\"output\":\"[^\"]*\"", "\"output\":\"relative.mp4\""), "relative output");
        expectFail(dir, good.replaceFirst("\"replay\":\"[^\"]*\"", "\"replay\":\"C:\\\\\\\\nope\\\\\\\\missing.zip\""), "missing replay");
        expectFail(dir, "{\"version\":1,\"replay\":" + quote(replay) + ",\"jobs\":[]}", "no jobs");
        expectFail(dir, "[1,2]", "not an object");
        expectFail(dir, "{{{", "garbage");
        String two = good.replace("\"jobs\":[", "\"jobs\":[" + good.substring(good.indexOf("{\"scene\""), good.length() - 2) + ",");
        expectFail(dir, two, "duplicate output");
        try {
            JobSpec.parse(dir.resolve("does_not_exist.json"));
            check(false, "missing job file must fail");
        } catch (JobSpec.JobException e) {
            check(true, "missing job file fails");
        }
        write(job, good.replace("\"version\":1", "\"version\":1,\"watchdog_s\":600"));
        check(JobSpec.parse(job).watchdogSeconds == 600, "custom watchdog");

        // ---- StatusWriter
        StatusWriter sw = new StatusWriter(job);
        sw.state = "exporting";
        sw.jobCount = 2;
        sw.jobIndex = 1;
        sw.jobName = "x";
        sw.progressPct = 42;
        JsonObject r = new JsonObject();
        r.addProperty("ok", true);
        sw.addResult(r);
        sw.addError("boom", new RuntimeException("trace me"));
        sw.write();
        JsonObject st = JsonParser.parseString(Files.readString(sw.path())).getAsJsonObject();
        check("exporting".equals(st.get("state").getAsString()), "status state");
        check(st.get("progressPct").getAsInt() == 42, "status progress");
        check(st.getAsJsonArray("results").size() == 1, "status results");
        check(st.getAsJsonArray("errors").get(0).getAsJsonObject().get("stack").getAsString().contains("trace me"), "status stack trace");
        check(st.get("pid").getAsLong() == ProcessHandle.current().pid(), "status pid");
        check(!Files.exists(job.resolveSibling("status.json.tmp")), "no leftover tmp");

        System.out.println(checks + " checks, " + failures + " failures");
        System.exit(failures == 0 ? 0 : 1);
    }

    private static String quote(Path p) {
        return "\"" + p.toString().replace("\\", "\\\\") + "\"";
    }

    private static void expectFail(Path dir, String json, String what) throws Exception {
        Path f = dir.resolve("bad.json");
        write(f, json);
        try {
            JobSpec.parse(f);
            check(false, "should reject: " + what);
        } catch (JobSpec.JobException e) {
            check(true, "rejects " + what + " -> " + e.getMessage());
        }
    }
}

