"""Hands-off Flashback export through the `flashback_auto` Fabric mod (studio/tools/flashback_auto).

Safe to import and test without Minecraft: nothing is launched unless ``launch=True`` (or env MCS_FLASHBACK_AUTO_LAUNCH=1).

Flow of :meth:`FlashbackAutoExporter.export` (the exact steps the studio takes):

1. parse + validate the job file (same rules as the mod's JobSpec); refuse when outputs are outside ``out_dir``
2. refuse when another Minecraft/javaw is running (autopilot-style probe, see ``launch_render.running_minecraft``)
3. delete stale ``status.json`` / ``STOP`` from the job folder, write ``ARMED`` (``{"job", "created", "token", "pid"}``) next to the job file
4. build the command (``launch_render.build_plan``: ``-Dflashback_auto.job=<job file>``, ``-Dflashback_auto.token=<token>``,
   ``-Dfabric.addMods=<mod jar>``) and start the game, below-normal priority, stdout to ``game_stdout.log``
5. poll ``status.json`` (state starting|opening|exporting|done|failed, progress, results, errors) until the mod reports a final
   state (then wait for the game to quit), the game exits, no status appears (startup timeout), the status goes stale, a STOP file
   is left unanswered, or the overall timeout expires -> kill the process tree (``taskkill /T /F``)
6. ``finally``: kill the game if it is still alive and remove ``ARMED`` (the mod is inert again)
7. one :class:`Result` per job in the job file (output existence and size are re-checked here)

Per-job interface used by ``mcstudio.cinematic`` (``Exporter.render(job) -> Path | None``) is :meth:`FlashbackAutoExporter.render`:
it writes a one-shot job file for a cinematic job, installs that job's editor state for the replay (the creator's original
``editor_states/<uuid>.json`` is backed up and restored afterwards) and runs :meth:`export`. Use :meth:`render_batch` to export
many cinematic jobs of one replay in one game launch.
"""
from __future__ import annotations

import importlib.util
import json
import os
import re
import shutil
import subprocess
import sys
import time
import uuid
import zipfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable

STUDIO = Path(__file__).resolve().parents[1]
LAUNCHER_PATH = STUDIO / "tools" / "flashback_auto" / "launch_render.py"
JOBS_DIR = STUDIO / "cinematic_jobs"
MC_DIR = Path(os.environ.get("APPDATA", str(Path.home() / "AppData/Roaming"))) / ".minecraft"

ARMED = "ARMED"
STOP = "STOP"
STATUS = "status.json"
FINAL_STATES = ("done", "failed")
CONTAINERS = {"MP4", "MKV", "AVI", "MOV", "PNG_SEQUENCE", "WEBP", "WEBM", "GIF"}
CODECS = {"H264", "H265", "AV1", "VP9", "PRO_RES", "QUICK_TIME", "WEBP", "GIF"}
ARMED_MAX_AGE_S = 600


class FlashbackAutoError(RuntimeError):
    pass


class JobFileError(FlashbackAutoError):
    def __init__(self, problems: list[str]):
        super().__init__("; ".join(problems))
        self.problems = problems


@dataclass
class Result:
    name: str
    output: Path | None
    ok: bool
    bytes: int = 0
    frames: int = 0
    duration_s: float = 0.0
    wall_s: float = 0.0
    scene: int | None = None
    message: str = ""


@dataclass
class JobFile:
    path: Path
    replay: Path
    shots: list[dict]
    watchdog_s: int = 2700


# ------------------------------------------------------------------------------------------------ launcher module
_launcher = None


def launcher():
    """tools/flashback_auto/launch_render.py loaded by path (it is a script, not a package)."""
    global _launcher
    if _launcher is None:
        spec = importlib.util.spec_from_file_location("flashback_auto_launch_render", LAUNCHER_PATH)
        mod = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = mod
        spec.loader.exec_module(mod)
        _launcher = mod
    return _launcher


# ------------------------------------------------------------------------------------------------ job file
def _is_int(x) -> bool:
    return isinstance(x, (int, float)) and not isinstance(x, bool) and float(x) == int(x)


def parse_jobs(path: str | Path) -> JobFile:
    """Read + validate a job file (mirror of the mod's JobSpec rules). Raises JobFileError listing every problem."""
    path = Path(path).resolve()
    errs: list[str] = []
    try:
        root = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise JobFileError([f"cannot read job file {path}: {e}"]) from e
    if not isinstance(root, dict):
        raise JobFileError(["job file is not a JSON object"])
    if root.get("version") != 1:
        errs.append("version must be 1")
    replay = root.get("replay")
    rp = None
    if not isinstance(replay, str) or not replay.strip():
        errs.append("replay path missing")
    else:
        rp = Path(replay)
        if not rp.is_absolute():
            errs.append(f"replay path must be absolute: {replay}")
        elif rp.suffix.lower() != ".zip":
            errs.append(f"replay must be a Flashback .zip: {replay}")
        elif not rp.is_file():
            errs.append(f"replay file not found: {replay}")
    wd = root.get("watchdog_s", 2700)
    if not (_is_int(wd) and 60 <= wd <= 21600):
        errs.append("watchdog_s must be an integer between 60 and 21600")
    jobs = root.get("jobs")
    shots: list[dict] = []
    if not isinstance(jobs, list) or not jobs:
        errs.append("jobs must be a non-empty array")
    elif len(jobs) > 200:
        errs.append(f"too many jobs ({len(jobs)} > 200)")
    else:
        seen: set[str] = set()
        for i, j in enumerate(jobs):
            w = f"jobs[{i}]"
            if not isinstance(j, dict):
                errs.append(f"{w} is not an object")
                continue
            e0 = len(errs)
            if not (_is_int(j.get("scene")) and 0 <= j["scene"] <= 1000):
                errs.append(f"{w}: scene must be an integer 0..1000")
            if not (isinstance(j.get("name"), str) and re.fullmatch(r"[A-Za-z0-9_.@-]{1,120}", j["name"])):
                errs.append(f"{w}: name must match [A-Za-z0-9_.@-]{{1,120}}")
            s, e = j.get("start"), j.get("end")
            if (s is None) != (e is None):
                errs.append(f"{w}: give both start and end, or neither")
            elif s is not None:
                if not (_is_int(s) and _is_int(e)):
                    errs.append(f"{w}: start/end must be integers")
                elif e <= s:
                    errs.append(f"{w}: end must be greater than start")
            out = j.get("output")
            if not isinstance(out, str) or not Path(out).is_absolute():
                errs.append(f"{w}: output must be an absolute path")
            elif out.lower() in seen:
                errs.append(f"{w}: duplicate output {out}")
            else:
                seen.add(out.lower())
            wd_, ht_ = j.get("width", 1920), j.get("height", 1080)
            if not (_is_int(wd_) and _is_int(ht_) and 64 <= wd_ <= 7680 and 64 <= ht_ <= 4320 and wd_ % 2 == 0 and ht_ % 2 == 0):
                errs.append(f"{w}: width/height must be even, 64..7680 x 64..4320")
            fps = j.get("fps", 60.0)
            if not (isinstance(fps, (int, float)) and not isinstance(fps, bool) and 1 <= fps <= 240):
                errs.append(f"{w}: fps must be 1..240")
            cont = str(j.get("container") or "MP4").upper()
            if cont not in CONTAINERS:
                errs.append(f"{w}: unknown container {cont}")
            if str(j.get("codec") or "H264").upper() not in CODECS:
                errs.append(f"{w}: unknown codec {j.get('codec')}")
            enc = j.get("encoder")
            if enc is not None and enc != "" and not re.fullmatch(r"[A-Za-z0-9_]{1,40}", str(enc)):
                errs.append(f"{w}: invalid encoder name {enc}")
            br = j.get("bitrate", 20_000_000)
            if not (_is_int(br) and 0 <= br <= 2_000_000_000):
                errs.append(f"{w}: bitrate must be 0..2000000000")
            if isinstance(out, str) and cont in CONTAINERS and cont != "PNG_SEQUENCE" \
                    and not out.lower().endswith("." + cont.lower()):
                errs.append(f"{w}: output should end with .{cont.lower()}")
            if len(errs) == e0:
                shots.append(j)
    if errs:
        raise JobFileError(errs)
    return JobFile(path=path, replay=rp, shots=shots, watchdog_s=int(wd))


# ------------------------------------------------------------------------------------------------ ARMED (python mirror of ArmedCheck.java)
def armed_check(job_prop: str | None, token_prop: str | None = None, now: float | None = None) -> tuple[bool, str]:
    """Same decision the mod takes at startup. (False, reason) means the mod does nothing at all."""
    if not job_prop:
        return False, "no -Dflashback_auto.job"
    job = Path(job_prop).resolve()
    marker = job.with_name(ARMED)
    if not marker.is_file():
        return False, "no ARMED marker next to the job file"
    try:
        m = json.loads(marker.read_text(encoding="utf-8"))
        mjob, created = Path(str(m["job"])).resolve(), float(m["created"])
    except (OSError, ValueError, KeyError, TypeError):
        return False, "ARMED marker unreadable or incomplete"
    if str(mjob).lower() != str(job).lower():
        return False, "ARMED marker names a different job file"
    age = (time.time() if now is None else now) - created
    if age > ARMED_MAX_AGE_S:
        return False, f"ARMED marker is stale ({int(age)} s old)"
    if age < -60:
        return False, "ARMED marker is dated in the future"
    if "token" in m and (token_prop is None or token_prop != m["token"]):
        return False, "ARMED token does not match"
    return True, "armed"


def read_status(job_file: str | Path) -> dict | None:
    p = Path(job_file).with_name(STATUS)
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else None
    except (OSError, ValueError):
        return None   # missing, or caught mid-write (the mod replaces the file atomically, but be tolerant)


# ------------------------------------------------------------------------------------------------ exporter
def _env_launch() -> bool:
    return os.environ.get("MCS_FLASHBACK_AUTO_LAUNCH", "") == "1"


def _output_state(out: Path) -> tuple[bool, int]:
    try:
        if out.is_dir():
            files = [f for f in out.iterdir() if f.is_file()]
            return bool(files), sum(f.stat().st_size for f in files)
        if out.is_file():
            n = out.stat().st_size
            return n > 0, n
    except OSError:
        pass
    return False, 0


class FlashbackAutoExporter:
    """Exporter backend ``flashback_auto`` (see module docstring)."""

    name = "flashback_auto"

    def __init__(self, launch: bool | None = None, mod_jar: str | Path | None = None, mc_dir: str | Path | None = None,
                 poll_s: float = 1.0, startup_timeout_s: float = 420.0, stale_status_s: float = 120.0,
                 exit_grace_s: float = 90.0, stop_grace_s: float = 45.0, xmx: str | None = None, username: str | None = None,
                 spawn: Callable | None = None, list_processes: Callable | None = None):
        self.launch = _env_launch() if launch is None else launch
        self.mod_jar = mod_jar
        self.mc_dir = Path(mc_dir) if mc_dir else MC_DIR
        self.poll_s = poll_s
        self.startup_timeout_s = startup_timeout_s
        self.stale_status_s = stale_status_s
        self.exit_grace_s = exit_grace_s
        self.stop_grace_s = stop_grace_s
        self.xmx, self.username = xmx, username
        self.spawn = spawn                # (plan, log_path) -> process with poll()/kill_tree()/pid ; default launch_render.launch
        self.list_processes = list_processes
        self.last_plan = None
        self.last_reason = ""

    # ---------------------------------------------------------------- helpers
    def _plan(self, job_path: Path, token: str):
        L = launcher()
        kw = {"mc_dir": self.mc_dir}
        if self.mod_jar:
            kw["mod_jar"] = self.mod_jar
        if self.xmx:
            kw["xmx"] = self.xmx
        if self.username:
            kw["username"] = self.username
        return L.build_plan(job_path, token, **kw)

    def request_stop(self, jobs_json_path: str | Path) -> None:
        """Kill switch: the mod aborts the export and stops the game when this file appears in the job folder."""
        Path(jobs_json_path).resolve().with_name(STOP).write_text("stop\n", encoding="utf-8")

    # ---------------------------------------------------------------- main entry
    def export(self, jobs_json_path: str | Path, out_dir: str | Path | None = None, timeout_s: float = 2700,
               launch: bool | None = None) -> list[Result]:
        job_path = Path(jobs_json_path).resolve()
        jf = parse_jobs(job_path)
        if out_dir is not None:
            root = Path(out_dir).resolve()
            for s in jf.shots:
                o = Path(s["output"]).resolve()
                if root != o and root not in o.parents:
                    raise JobFileError([f"output {o} is outside out_dir {root}"])
        do_launch = self.launch if launch is None else launch
        token = uuid.uuid4().hex
        if not do_launch:
            self.last_plan = self._plan(job_path, "DRYRUN")
            self.last_reason = "dry run"
            msg = "dry run: game not launched" + (f" (missing: {self.last_plan.missing})" if self.last_plan.missing else "")
            return [Result(s["name"], Path(s["output"]), False, scene=s["scene"], message=msg) for s in jf.shots]

        L = launcher()
        others = L.running_minecraft(self.list_processes)
        if others:
            raise FlashbackAutoError("another Minecraft is running (pid " + ", ".join(str(o["pid"]) for o in others)
                                     + "); close it first, nothing was launched")
        plan = self._plan(job_path, token)
        self.last_plan = plan
        if plan.missing:
            raise FlashbackAutoError("cannot launch, missing: " + "; ".join(plan.missing))
        folder = job_path.parent
        for stale in (STATUS, STOP, STATUS + ".tmp", "flashback_auto.log", "game_stdout.log"):
            try:
                (folder / stale).unlink()
            except FileNotFoundError:
                pass
        for s in jf.shots:
            Path(s["output"]).parent.mkdir(parents=True, exist_ok=True)

        proc = None
        t0 = time.time()
        reason = ""
        try:
            L.write_armed(job_path, token)
            log = folder / "game_stdout.log"
            proc = self.spawn(plan, log) if self.spawn else L.launch(plan, log, list_processes=self.list_processes)
            reason = self._monitor(proc, job_path, min(timeout_s, jf.watchdog_s + 120), t0)
        finally:
            try:
                if proc is not None and proc.poll() is None:
                    proc.kill_tree()
            finally:
                L.disarm(job_path)
        self.last_reason = reason
        return self._collect(jf, job_path, proc, reason, time.time() - t0)

    def _monitor(self, proc, job_path: Path, timeout_s: float, t0: float) -> str:
        """Returns '' when the mod reported a final state / the game ended, else the reason we gave up."""
        saw = False
        last_upd = None
        last_change = time.time()
        final_at = None
        stop_seen = None
        stop_file = job_path.with_name(STOP)
        while True:
            now = time.time()
            st = read_status(job_path)
            if st:
                saw = True
                if st.get("updatedMs") != last_upd:
                    last_upd, last_change = st.get("updatedMs"), now
                if st.get("state") in FINAL_STATES and final_at is None:
                    final_at = now
            if proc.poll() is not None:
                return "" if (st and st.get("state") in FINAL_STATES) else f"game exited (code {proc.poll()}) before finishing"
            if final_at is not None and now - final_at > self.exit_grace_s:
                return "mod finished but the game did not exit"
            if not saw and now - t0 > self.startup_timeout_s:
                return (f"no status.json after {int(now - t0)} s: the mod did not start (not loaded, not armed, or the game "
                        "is stuck loading)")
            if saw and final_at is None and now - last_change > self.stale_status_s:
                return f"status.json not updated for {int(now - last_change)} s"
            if stop_file.exists():
                stop_seen = stop_seen or now
                if now - stop_seen > self.stop_grace_s:
                    return "STOP requested and the game did not quit"
            if now - t0 > timeout_s:
                return f"timeout after {int(now - t0)} s"
            time.sleep(self.poll_s)

    def _collect(self, jf: JobFile, job_path: Path, proc, reason: str, wall: float) -> list[Result]:
        st = read_status(job_path) or {}
        by_name = {r.get("name"): r for r in st.get("results", []) if isinstance(r, dict)}
        errors = "; ".join(str(e.get("message", e)) for e in st.get("errors", []) if isinstance(e, (dict, str)))
        why = reason or (st.get("message") if st.get("state") == "failed" else "")
        out: list[Result] = []
        for s in jf.shots:
            o = Path(s["output"])
            ok_file, size = _output_state(o)
            r = by_name.get(s["name"])
            if r is not None:
                ok = bool(r.get("ok")) and ok_file
                msg = r.get("message", "") or ("" if ok else "output file missing or empty")
                out.append(Result(s["name"], o, ok, size, int(r.get("frames", 0)), float(r.get("durationS", 0.0)),
                                  float(r.get("wallS", 0.0)), s["scene"], msg))
            else:
                msg = why or errors or "mod reported no result for this shot"
                if st.get("state"):
                    msg = f"[{st.get('state')}] {msg}"
                out.append(Result(s["name"], o, False, size, scene=s["scene"], message=msg))
        if proc is not None and reason:
            crash = self._newest_crash_report(time.time() - wall - 5)
            if crash:
                for r in out:
                    if not r.ok:
                        r.message += f" (crash report: {crash})"
        return out

    def _newest_crash_report(self, since: float) -> str | None:
        d = self.mc_dir / "crash-reports"
        try:
            files = sorted(d.glob("crash-*.txt"), key=lambda p: p.stat().st_mtime)
            return str(files[-1]) if files and files[-1].stat().st_mtime >= since else None
        except OSError:
            return None

    # ---------------------------------------------------------------- cinematic interface
    @staticmethod
    def _replay_uuid(replay: Path) -> str:
        with zipfile.ZipFile(replay) as z:
            return str(json.loads(z.read("metadata.json").decode("utf-8"))["uuid"])

    @staticmethod
    def _codec(name: str | None) -> str:
        return {"h264": "H264", "h265": "H265", "hevc": "H265", "av1": "AV1", "vp9": "VP9"}.get(str(name or "h264").lower(), "H264")

    def _shot_for_job(self, job: dict, scene: int) -> dict:
        ex = job["export"]
        rng = (job.get("camera", {}).get("keyframes") or {}).get("export_range_ticks") or [job.get("tick_start"), job.get("tick_end")]
        start, end = (rng + [None, None])[:2]
        vis = job.get("visuals", {})
        return {"scene": scene, "name": re.sub(r"[^A-Za-z0-9_.@-]+", "_", job["job_id"] + "_" + str(job.get("shot_id", ""))),
                "start": start, "end": end, "output": str(Path(ex["output_abs"])), "width": int(ex["width"]),
                "height": int(ex["height"]), "fps": float(ex["fps"]), "container": "MP4", "codec": self._codec(ex.get("codec")),
                "encoder": None, "bitrate": int(ex.get("bitrate", 20_000_000)), "ssaa": False, "noGui": bool(vis.get("hide_gui", True)),
                "resetRng": False, "recordAudio": False, "transparent": False, "kind": job.get("kind", ""), "note": job["job_id"]}

    def render_batch(self, jobs: list[dict]) -> list[Result]:
        """Export several cinematic jobs of the SAME replay in one game launch (one scene per job)."""
        if not jobs:
            return []
        replays = {j["replay"]["path"] for j in jobs}
        if len(replays) != 1 or not next(iter(replays)):
            raise FlashbackAutoError("render_batch needs jobs that all reference the same replay path")
        replay = Path(replays.pop())
        project = jobs[0]["project"]
        run_dir = JOBS_DIR / project / f"run-{jobs[0]['job_id']}-x{len(jobs)}"
        run_dir.mkdir(parents=True, exist_ok=True)
        # one editor state with one scene per job
        states, shots = [], []
        for i, j in enumerate(jobs):
            kf = (j.get("camera") or {}).get("keyframes")
            if not kf or kf.get("errors") or not kf.get("editor_state"):
                raise FlashbackAutoError(f"{j['job_id']}: no valid camera keyframes (editor_state) in the job; re-run queue "
                                         "with the replay available")
            states.append(kf["editor_state"])
            shots.append(self._shot_for_job(j, i))
        state = json.loads(json.dumps(states[0]))
        state["scenes"] = [st["scenes"][0] for st in states]
        state["sceneIndex"] = 0
        job_file = run_dir / "jobs.json"
        job_file.write_text(json.dumps({"version": 1, "replay": str(replay), "jobs": shots}, indent=1), encoding="utf-8")
        if not self.launch:
            return self.export(job_file, launch=False)

        from mcstudio import flashback_keyframes as FK
        errs = FK.validate_state(state)
        if errs:
            raise FlashbackAutoError("invalid editor state: " + "; ".join(errs[:3]))
        ed = self.mc_dir / "flashback" / "editor_states"
        target = ed / f"{self._replay_uuid(replay)}.json"
        backup = target.with_name(target.name + ".flashback_auto_backup")
        existed = target.exists()
        if existed and not backup.exists():
            shutil.copy2(target, backup)
        ed.mkdir(parents=True, exist_ok=True)
        target.write_text(FK.dumps_state(state), encoding="utf-8")
        try:
            return self.export(job_file, launch=True)
        finally:
            if existed:
                shutil.copy2(backup, target)       # put the creator's own editor state back
                backup.unlink(missing_ok=True)
            else:
                target.unlink(missing_ok=True)

    def render(self, job: dict) -> Path | None:
        """Exporter interface of mcstudio.cinematic: Path of the clip, None when it will arrive later (dry run), raises on failure."""
        out = Path(job["export"]["output_abs"])
        res = self.render_batch([job])[0]
        if res.ok:
            return out
        if res.message.startswith("dry run"):
            return None
        raise FlashbackAutoError(f"{job['job_id']}: {res.message}")

toolu_018SSrJL1rmzcdjAiZk1ywGd.content:
"""Hands-off Flashback export through the `flashback_auto` Fabric mod (studio/tools/flashback_auto).

Safe to import and test without Minecraft: nothing is launched unless ``launch=True`` (or env MCS_FLASHBACK_AUTO_LAUNCH=1).

Flow of :meth:`FlashbackAutoExporter.export` (the exact steps the studio takes):

1. parse + validate the job file (same rules as the mod's JobSpec); refuse when outputs are outside ``out_dir``
2. refuse when another Minecraft/javaw is running (autopilot-style probe, see ``launch_render.running_minecraft``)
3. delete stale ``status.json`` / ``STOP`` from the job folder, write ``ARMED`` (``{"job", "created", "token", "pid"}``) next to the job file
4. build the command (``launch_render.build_plan``: ``-Dflashback_auto.job=<job file>``, ``-Dflashback_auto.token=<token>``,
   ``-Dfabric.addMods=<mod jar>``) and start the game, below-normal priority, stdout to ``game_stdout.log``
5. poll ``status.json`` (state starting|opening|exporting|done|failed, progress, results, errors) until the mod reports a final
   state (then wait for the game to quit), the game exits, no status appears (startup timeout), the status goes stale, a STOP file
   is left unanswered, or the overall timeout expires -> kill the process tree (``taskkill /T /F``)
6. ``finally``: kill the game if it is still alive and remove ``ARMED`` (the mod is inert again)
7. one :class:`Result` per job in the job file (output existence and size are re-checked here)

Per-job interface used by ``mcstudio.cinematic`` (``Exporter.render(job) -> Path | None``) is :meth:`FlashbackAutoExporter.render`:
it writes a one-shot job file for a cinematic job, installs that job's editor state for the replay (the creator's original
``editor_states/<uuid>.json`` is backed up and restored afterwards) and runs :meth:`export`. Use :meth:`render_batch` to export
many cinematic jobs of one replay in one game launch.
"""
from __future__ import annotations

import importlib.util
import json
import os
import re
import shutil
import subprocess
import sys
import time
import uuid
import zipfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable

STUDIO = Path(__file__).resolve().parents[1]
LAUNCHER_PATH = STUDIO / "tools" / "flashback_auto" / "launch_render.py"
JOBS_DIR = STUDIO / "cinematic_jobs"
MC_DIR = Path(os.environ.get("APPDATA", str(Path.home() / "AppData/Roaming"))) / ".minecraft"

ARMED = "ARMED"
STOP = "STOP"
STATUS = "status.json"
FINAL_STATES = ("done", "failed")
CONTAINERS = {"MP4", "MKV", "AVI", "MOV", "PNG_SEQUENCE", "WEBP", "WEBM", "GIF"}
CODECS = {"H264", "H265", "AV1", "VP9", "PRO_RES", "QUICK_TIME", "WEBP", "GIF"}
ARMED_MAX_AGE_S = 600


class FlashbackAutoError(RuntimeError):
    pass


class JobFileError(FlashbackAutoError):
    def __init__(self, problems: list[str]):
        super().__init__("; ".join(problems))
        self.problems = problems


@dataclass
class Result:
    name: str
    output: Path | None
    ok: bool
    bytes: int = 0
    frames: int = 0
    duration_s: float = 0.0
    wall_s: float = 0.0
    scene: int | None = None
    message: str = ""


@dataclass
class JobFile:
    path: Path
    replay: Path
    shots: list[dict]
    watchdog_s: int = 2700


# ------------------------------------------------------------------------------------------------ launcher module
_launcher = None


def launcher():
    """tools/flashback_auto/launch_render.py loaded by path (it is a script, not a package)."""
    global _launcher
    if _launcher is None:
        spec = importlib.util.spec_from_file_location("flashback_auto_launch_render", LAUNCHER_PATH)
        mod = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = mod
        spec.loader.exec_module(mod)
        _launcher = mod
    return _launcher


# ------------------------------------------------------------------------------------------------ job file
def _is_int(x) -> bool:
    return isinstance(x, (int, float)) and not isinstance(x, bool) and float(x) == int(x)


def parse_jobs(path: str | Path) -> JobFile:
    """Read + validate a job file (mirror of the mod's JobSpec rules). Raises JobFileError listing every problem."""
    path = Path(path).resolve()
    errs: list[str] = []
    try:
        root = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise JobFileError([f"cannot read job file {path}: {e}"]) from e
    if not isinstance(root, dict):
        raise JobFileError(["job file is not a JSON object"])
    if root.get("version") != 1:
        errs.append("version must be 1")
    replay = root.get("replay")
    rp = None
    if not isinstance(replay, str) or not replay.strip():
        errs.append("replay path missing")
    else:
        rp = Path(replay)
        if not rp.is_absolute():
            errs.append(f"replay path must be absolute: {replay}")
        elif rp.suffix.lower() != ".zip":
            errs.append(f"replay must be a Flashback .zip: {replay}")
        elif not rp.is_file():
            errs.append(f"replay file not found: {replay}")
    wd = root.get("watchdog_s", 2700)
    if not (_is_int(wd) and 60 <= wd <= 21600):
        errs.append("watchdog_s must be an integer between 60 and 21600")
    jobs = root.get("jobs")
    shots: list[dict] = []
    if not isinstance(jobs, list) or not jobs:
        errs.append("jobs must be a non-empty array")
    elif len(jobs) > 200:
        errs.append(f"too many jobs ({len(jobs)} > 200)")
    else:
        seen: set[str] = set()
        for i, j in enumerate(jobs):
            w = f"jobs[{i}]"
            if not isinstance(j, dict):
                errs.append(f"{w} is not an object")
                continue
            e0 = len(errs)
            if not (_is_int(j.get("scene")) and 0 <= j["scene"] <= 1000):
                errs.append(f"{w}: scene must be an integer 0..1000")
            if not (isinstance(j.get("name"), str) and re.fullmatch(r"[A-Za-z0-9_.@-]{1,120}", j["name"])):
                errs.append(f"{w}: name must match [A-Za-z0-9_.@-]{{1,120}}")
            s, e = j.get("start"), j.get("end")
            if (s is None) != (e is None):
                errs.append(f"{w}: give both start and end, or neither")
            elif s is not None:
                if not (_is_int(s) and _is_int(e)):
                    errs.append(f"{w}: start/end must be integers")
                elif e <= s:
                    errs.append(f"{w}: end must be greater than start")
            out = j.get("output")
            if not isinstance(out, str) or not Path(out).is_absolute():
                errs.append(f"{w}: output must be an absolute path")
            elif out.lower() in seen:
                errs.append(f"{w}: duplicate output {out}")
            else:
                seen.add(out.lower())
            wd_, ht_ = j.get("width", 1920), j.get("height", 1080)
            if not (_is_int(wd_) and _is_int(ht_) and 64 <= wd_ <= 7680 and 64 <= ht_ <= 4320 and wd_ % 2 == 0 and ht_ % 2 == 0):
                errs.append(f"{w}: width/height must be even, 64..7680 x 64..4320")
            fps = j.get("fps", 60.0)
            if not (isinstance(fps, (int, float)) and not isinstance(fps, bool) and 1 <= fps <= 240):
                errs.append(f"{w}: fps must be 1..240")
            cont = str(j.get("container") or "MP4").upper()
            if cont not in CONTAINERS:
                errs.append(f"{w}: unknown container {cont}")
            if str(j.get("codec") or "H264").upper() not in CODECS:
                errs.append(f"{w}: unknown codec {j.get('codec')}")
            enc = j.get("encoder")
            if enc is not None and enc != "" and not re.fullmatch(r"[A-Za-z0-9_]{1,40}", str(enc)):
                errs.append(f"{w}: invalid encoder name {enc}")
            br = j.get("bitrate", 20_000_000)
            if not (_is_int(br) and 0 <= br <= 2_000_000_000):
                errs.append(f"{w}: bitrate must be 0..2000000000")
            if isinstance(out, str) and cont in CONTAINERS and cont != "PNG_SEQUENCE" \
                    and not out.lower().endswith("." + cont.lower()):
                errs.append(f"{w}: output should end with .{cont.lower()}")
            if len(errs) == e0:
                shots.append(j)
    if errs:
        raise JobFileError(errs)
    return JobFile(path=path, replay=rp, shots=shots, watchdog_s=int(wd))


# ------------------------------------------------------------------------------------------------ ARMED (python mirror of ArmedCheck.java)
def armed_check(job_prop: str | None, token_prop: str | None = None, now: float | None = None) -> tuple[bool, str]:
    """Same decision the mod takes at startup. (False, reason) means the mod does nothing at all."""
    if not job_prop:
        return False, "no -Dflashback_auto.job"
    job = Path(job_prop).resolve()
    marker = job.with_name(ARMED)
    if not marker.is_file():
        return False, "no ARMED marker next to the job file"
    try:
        m = json.loads(marker.read_text(encoding="utf-8"))
        mjob, created = Path(str(m["job"])).resolve(), float(m["created"])
    except (OSError, ValueError, KeyError, TypeError):
        return False, "ARMED marker unreadable or incomplete"
    if str(mjob).lower() != str(job).lower():
        return False, "ARMED marker names a different job file"
    age = (time.time() if now is None else now) - created
    if age > ARMED_MAX_AGE_S:
        return False, f"ARMED marker is stale ({int(age)} s old)"
    if age < -60:
        return False, "ARMED marker is dated in the future"
    if "token" in m and (token_prop is None or token_prop != m["token"]):
        return False, "ARMED token does not match"
    return True, "armed"


def read_status(job_file: str | Path) -> dict | None:
    p = Path(job_file).with_name(STATUS)
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
        return d if isinstance(d, dict) else None
    except (OSError, ValueError):
        return None   # missing, or caught mid-write (the mod replaces the file atomically, but be tolerant)


# ------------------------------------------------------------------------------------------------ exporter
def _env_launch() -> bool:
    return os.environ.get("MCS_FLASHBACK_AUTO_LAUNCH", "") == "1"


def _output_state(out: Path) -> tuple[bool, int]:
    try:
        if out.is_dir():
            files = [f for f in out.iterdir() if f.is_file()]
            return bool(files), sum(f.stat().st_size for f in files)
        if out.is_file():
            n = out.stat().st_size
            return n > 0, n
    except OSError:
        pass
    return False, 0


class FlashbackAutoExporter:
    """Exporter backend ``flashback_auto`` (see module docstring)."""

    name = "flashback_auto"

    def __init__(self, launch: bool | None = None, mod_jar: str | Path | None = None, mc_dir: str | Path | None = None,
                 poll_s: float = 1.0, startup_timeout_s: float = 420.0, stale_status_s: float = 120.0,
                 exit_grace_s: float = 90.0, stop_grace_s: float = 45.0, xmx: str | None = None, username: str | None = None,
                 spawn: Callable | None = None, list_processes: Callable | None = None):
        self.launch = _env_launch() if launch is None else launch
        self.mod_jar = mod_jar
        self.mc_dir = Path(mc_dir) if mc_dir else MC_DIR
        self.poll_s = poll_s
        self.startup_timeout_s = startup_timeout_s
        self.stale_status_s = stale_status_s
        self.exit_grace_s = exit_grace_s
        self.stop_grace_s = stop_grace_s
        self.xmx, self.username = xmx, username
        self.spawn = spawn                # (plan, log_path) -> process with poll()/kill_tree()/pid ; default launch_render.launch
        self.list_processes = list_processes
        self.last_plan = None
        self.last_reason = ""

    # ---------------------------------------------------------------- helpers
    def _plan(self, job_path: Path, token: str):
        L = launcher()
        kw = {"mc_dir": self.mc_dir}
        if self.mod_jar:
            kw["mod_jar"] = self.mod_jar
        if self.xmx:
            kw["xmx"] = self.xmx
        if self.username:
            kw["username"] = self.username
        return L.build_plan(job_path, token, **kw)

    def request_stop(self, jobs_json_path: str | Path) -> None:
        """Kill switch: the mod aborts the export and stops the game when this file appears in the job folder."""
        Path(jobs_json_path).resolve().with_name(STOP).write_text("stop\n", encoding="utf-8")

    # ---------------------------------------------------------------- main entry
    def export(self, jobs_json_path: str | Path, out_dir: str | Path | None = None, timeout_s: float = 2700,
               launch: bool | None = None) -> list[Result]:
        job_path = Path(jobs_json_path).resolve()
        jf = parse_jobs(job_path)
        if out_dir is not None:
            root = Path(out_dir).resolve()
            for s in jf.shots:
                o = Path(s["output"]).resolve()
                if root != o and root not in o.parents:
                    raise JobFileError([f"output {o} is outside out_dir {root}"])
        do_launch = self.launch if launch is None else launch
        token = uuid.uuid4().hex
        if not do_launch:
            self.last_plan = self._plan(job_path, "DRYRUN")
            self.last_reason = "dry run"
            msg = "dry run: game not launched" + (f" (missing: {self.last_plan.missing})" if self.last_plan.missing else "")
            return [Result(s["name"], Path(s["output"]), False, scene=s["scene"], message=msg) for s in jf.shots]

        L = launcher()
        others = L.running_minecraft(self.list_processes)
        if others:
            raise FlashbackAutoError("another Minecraft is running (pid " + ", ".join(str(o["pid"]) for o in others)
                                     + "); close it first, nothing was launched")
        plan = self._plan(job_path, token)
        self.last_plan = plan
        if plan.missing:
            raise FlashbackAutoError("cannot launch, missing: " + "; ".join(plan.missing))
        folder = job_path.parent
        for stale in (STATUS, STOP, STATUS + ".tmp", "flashback_auto.log", "game_stdout.log"):
            try:
                (folder / stale).unlink()
            except FileNotFoundError:
                pass
        for s in jf.shots:
            Path(s["output"]).parent.mkdir(parents=True, exist_ok=True)

        proc = None
        t0 = time.time()
        reason = ""
        try:
            L.write_armed(job_path, token)
            log = folder / "game_stdout.log"
            proc = self.spawn(plan, log) if self.spawn else L.launch(plan, log, list_processes=self.list_processes)
            reason = self._monitor(proc, job_path, min(timeout_s, jf.watchdog_s + 120), t0)
        finally:
            try:
                if proc is not None and proc.poll() is None:
                    proc.kill_tree()
            finally:
                L.disarm(job_path)
        self.last_reason = reason
        return self._collect(jf, job_path, proc, reason, time.time() - t0)

    def _monitor(self, proc, job_path: Path, timeout_s: float, t0: float) -> str:
        """Returns '' when the mod reported a final state / the game ended, else the reason we gave up."""
        saw = False
        last_upd = None
        last_change = time.time()
        final_at = None
        stop_seen = None
        stop_file = job_path.with_name(STOP)
        while True:
            now = time.time()
            st = read_status(job_path)
            if st:
                saw = True
                if st.get("updatedMs") != last_upd:
                    last_upd, last_change = st.get("updatedMs"), now
                if st.get("state") in FINAL_STATES and final_at is None:
                    final_at = now
            if proc.poll() is not None:
                return "" if (st and st.get("state") in FINAL_STATES) else f"game exited (code {proc.poll()}) before finishing"
            if final_at is not None and now - final_at > self.exit_grace_s:
                return "mod finished but the game did not exit"
            if not saw and now - t0 > self.startup_timeout_s:
                return (f"no status.json after {int(now - t0)} s: the mod did not start (not loaded, not armed, or the game "
                        "is stuck loading)")
            if saw and final_at is None and now - last_change > self.stale_status_s:
                return f"status.json not updated for {int(now - last_change)} s"
            if stop_file.exists():
                stop_seen = stop_seen or now
                if now - stop_seen > self.stop_grace_s:
                    return "STOP requested and the game did not quit"
            if now - t0 > timeout_s:
                return f"timeout after {int(now - t0)} s"
            time.sleep(self.poll_s)

    def _collect(self, jf: JobFile, job_path: Path, proc, reason: str, wall: float) -> list[Result]:
        st = read_status(job_path) or {}
        by_name = {r.get("name"): r for r in st.get("results", []) if isinstance(r, dict)}
        errors = "; ".join(str(e.get("message", e)) for e in st.get("errors", []) if isinstance(e, (dict, str)))
        why = reason or (st.get("message") if st.get("state") == "failed" else "")
        out: list[Result] = []
        for s in jf.shots:
            o = Path(s["output"])
            ok_file, size = _output_state(o)
            r = by_name.get(s["name"])
            if r is not None:
                ok = bool(r.get("ok")) and ok_file
                msg = r.get("message", "") or ("" if ok else "output file missing or empty")
                out.append(Result(s["name"], o, ok, size, int(r.get("frames", 0)), float(r.get("durationS", 0.0)),
                                  float(r.get("wallS", 0.0)), s["scene"], msg))
            else:
                msg = why or errors or "mod reported no result for this shot"
                if st.get("state"):
                    msg = f"[{st.get('state')}] {msg}"
                out.append(Result(s["name"], o, False, size, scene=s["scene"], message=msg))
        if proc is not None and reason:
            crash = self._newest_crash_report(time.time() - wall - 5)
            if crash:
                for r in out:
                    if not r.ok:
                        r.message += f" (crash report: {crash})"
        return out

    def _newest_crash_report(self, since: float) -> str | None:
        d = self.mc_dir / "crash-reports"
        try:
            files = sorted(d.glob("crash-*.txt"), key=lambda p: p.stat().st_mtime)
            return str(files[-1]) if files and files[-1].stat().st_mtime >= since else None
        except OSError:
            return None

    # ---------------------------------------------------------------- cinematic interface
    @staticmethod
    def _replay_uuid(replay: Path) -> str:
        with zipfile.ZipFile(replay) as z:
            return str(json.loads(z.read("metadata.json").decode("utf-8"))["uuid"])

    @staticmethod
    def _codec(name: str | None) -> str:
        return {"h264": "H264", "h265": "H265", "hevc": "H265", "av1": "AV1", "vp9": "VP9"}.get(str(name or "h264").lower(), "H264")

    def _shot_for_job(self, job: dict, scene: int) -> dict:
        ex = job["export"]
        rng = (job.get("camera", {}).get("keyframes") or {}).get("export_range_ticks") or [job.get("tick_start"), job.get("tick_end")]
        start, end = (rng + [None, None])[:2]
        vis = job.get("visuals", {})
        return {"scene": scene, "name": re.sub(r"[^A-Za-z0-9_.@-]+", "_", job["job_id"] + "_" + str(job.get("shot_id", ""))),
                "start": start, "end": end, "output": str(Path(ex["output_abs"])), "width": int(ex["width"]),
                "height": int(ex["height"]), "fps": float(ex["fps"]), "container": "MP4", "codec": self._codec(ex.get("codec")),
                "encoder": None, "bitrate": int(ex.get("bitrate", 20_000_000)), "ssaa": False, "noGui": bool(vis.get("hide_gui", True)),
                "resetRng": False, "recordAudio": False, "transparent": False, "kind": job.get("kind", ""), "note": job["job_id"]}

    def render_batch(self, jobs: list[dict]) -> list[Result]:
        """Export several cinematic jobs of the SAME replay in one game launch (one scene per job)."""
        if not jobs:
            return []
        replays = {j["replay"]["path"] for j in jobs}
        if len(replays) != 1 or not next(iter(replays)):
            raise FlashbackAutoError("render_batch needs jobs that all reference the same replay path")
        replay = Path(replays.pop())
        project = jobs[0]["project"]
        run_dir = JOBS_DIR / project / f"run-{jobs[0]['job_id']}-x{len(jobs)}"
        run_dir.mkdir(parents=True, exist_ok=True)
        # one editor state with one scene per job
        states, shots = [], []
        for i, j in enumerate(jobs):
            kf = (j.get("camera") or {}).get("keyframes")
            if not kf or kf.get("errors") or not kf.get("editor_state"):
                raise FlashbackAutoError(f"{j['job_id']}: no valid camera keyframes (editor_state) in the job; re-run queue "
                                         "with the replay available")
            states.append(kf["editor_state"])
            shots.append(self._shot_for_job(j, i))
        state = json.loads(json.dumps(states[0]))
        state["scenes"] = [st["scenes"][0] for st in states]
        state["sceneIndex"] = 0
        job_file = run_dir / "jobs.json"
        job_file.write_text(json.dumps({"version": 1, "replay": str(replay), "jobs": shots}, indent=1), encoding="utf-8")
        if not self.launch:
            return self.export(job_file, launch=False)

        from mcstudio import flashback_keyframes as FK
        errs = FK.validate_state(state)
        if errs:
            raise FlashbackAutoError("invalid editor state: " + "; ".join(errs[:3]))
        ed = self.mc_dir / "flashback" / "editor_states"
        target = ed / f"{self._replay_uuid(replay)}.json"
        backup = target.with_name(target.name + ".flashback_auto_backup")
        existed = target.exists()
        if existed and not backup.exists():
            shutil.copy2(target, backup)
        ed.mkdir(parents=True, exist_ok=True)
        target.write_text(FK.dumps_state(state), encoding="utf-8")
        try:
            return self.export(job_file, launch=True)
        finally:
            if existed:
                shutil.copy2(backup, target)       # put the creator's own editor state back
                backup.unlink(missing_ok=True)
            else:
                target.unlink(missing_ok=True)

    def render(self, job: dict) -> Path | None:
        """Exporter interface of mcstudio.cinematic: Path of the clip, None when it will arrive later (dry run), raises on failure."""
        out = Path(job["export"]["output_abs"])
        res = self.render_batch([job])[0]
        if res.ok:
            return out
        if res.message.startswith("dry run"):
            return None
        raise FlashbackAutoError(f"{job['job_id']}: {res.message}")

